            assert(ownerBalAfter == ownerBalBefore - burnAmount);
            assert(totalSupplyAfter == totalSupplyBefore - burnAmount);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 value) public payable {
        require(to != msg.sender);
        uint256 supplyBefore = c.totalSupply();
        uint256 senderBefore = c.balanceOf(msg.sender);
        uint256 toBefore = c.balanceOf(to);

        bool reverted;
        try c.transfer(to, value) { reverted = false; } catch { reverted = true; }

        if (to == address(0)) {
            assert(reverted);
            assert(c.totalSupply() == supplyBefore);
            assert(c.balanceOf(msg.sender) == senderBefore);
        } else if (value > senderBefore || toBefore + value < toBefore) {
            assert(reverted);
            assert(c.totalSupply() == supplyBefore);
            assert(c.balanceOf(msg.sender) == senderBefore);
            assert(c.balanceOf(to) == toBefore);
        } else {
            assert(!reverted);
            assert(c.totalSupply() == supplyBefore);
            assert(c.balanceOf(msg.sender) == senderBefore - value);
            assert(c.balanceOf(to) == toBefore + value);
        }
    }

    receive() external payable {}
}

