contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address to, uint256 amount) public payable {
        require(from != address(0));
        require(to != address(0));
        require(from != to);

        uint256 fromBefore = c.balanceOf(from);
        uint256 toBefore = c.balanceOf(to);
        uint256 totalBefore = c.totalSupply();
        bool fromFrozen = c.frozenAccount(from);
        bool toFrozen = c.frozenAccount(to);

        bool success;
        try c.transferFrom(from, to, amount) {
            success = true;
        } catch {
            success = false;
        }

        assert(
            (!fromFrozen && !toFrozen && fromBefore >= amount && toBefore + amount >= toBefore)
                ? (success && c.balanceOf(from) == fromBefore - amount && c.balanceOf(to) == toBefore + amount && c.totalSupply() == totalBefore)
                : (!success && c.balanceOf(from) == fromBefore && c.balanceOf(to) == toBefore && c.totalSupply() == totalBefore)
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 value) public {
        require(to != address(0), "to must be nonzero");

        uint256 senderBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(to);
        uint256 zeroBefore = c.balanceOf(address(0));
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        try c.transfer(to, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 senderAfter = c.balanceOf(address(this));
        uint256 toAfter = c.balanceOf(to);
        uint256 zeroAfter = c.balanceOf(address(0));
        uint256 supplyAfter = c.totalSupply();

        if (reverted) {
            assert(senderAfter == senderBefore && toAfter == toBefore && zeroAfter == zeroBefore && supplyAfter == supplyBefore);
        } else {
            assert(senderBefore >= value);
            assert(senderAfter == senderBefore - value);
            assert(toAfter == toBefore + value);
            assert(zeroAfter == zeroBefore);
            assert(supplyAfter == supplyBefore);
        }
    }

    receive() external payable {}
}
